begin;
do $$declare
 staff uuid:=gen_random_uuid();outside_user uuid:=gen_random_uuid();profile uuid;org uuid:=gen_random_uuid();dir uuid:=gen_random_uuid();sh uuid:=gen_random_uuid();bl uuid:=gen_random_uuid();
 rider uuid:=gen_random_uuid();horse uuid:=gen_random_uuid();bt uuid:=gen_random_uuid();ct uuid:=gen_random_uuid();nrha_ct uuid:=gen_random_uuid();cl uuid:=gen_random_uuid();
 list uuid:=gen_random_uuid();edition uuid:=gen_random_uuid();a jsonb;blocked boolean;params jsonb;nrha uuid;issuer uuid;override_id uuid;
 pro uuid:=gen_random_uuid();pro_current uuid:=gen_random_uuid();rows jsonb;plan jsonb;stall uuid:=gen_random_uuid();booking uuid:=gen_random_uuid();day uuid;
begin
 insert into auth.users(id,email,raw_user_meta_data) values(staff,staff||'@example.test','{}'),(outside_user,outside_user||'@example.test','{}');
 select id into profile from public.user_profiles where user_id=staff;
 insert into public.organizations(id,name,slug) values(org,'House TEST',org::text);
 insert into public.organization_members(organization_id,user_id,role) values(org,profile,'secretary');
 insert into public.organization_disciplines(id,organization_id,discipline_id) values(dir,org,(select id from public.disciplines where code='REINING'));
 insert into public.contacts(id,type,first_name,last_name,date_of_birth) values(rider,'rider','Émilie','Test','1976-07-01');
 insert into public.directory_contacts(organization_discipline_id,contact_id) values(dir,rider);
 insert into public.horses(id,name,primary_owner_contact_id) values(horse,'House horse',rider);
 insert into public.directory_horses(organization_discipline_id,horse_id) values(dir,horse);
 insert into public.shows(id,organization_id,name,slug,start_date,end_date) values(sh,org,'House TEST',sh::text,'2026-10-01','2026-10-01');
 insert into public.blocks(id,organization_id,show_id,name) values(bl,org,sh,'Mixed block');
 insert into public.block_templates(id,organization_id,name) values(bt,org,'House templates');
 insert into public.class_templates(id,organization_id,block_template_id,organization_discipline_id,name,sort_order) values(ct,org,bt,dir,'House prime time',1),(nrha_ct,org,bt,dir,'Reference NRHA',2);
 insert into public.classes(id,organization_id,show_id,block_id,organization_discipline_id,class_template_id,name,entry_fee,sort_order) values(cl,org,sh,bl,dir,ct,'House prime time',0,1);
 insert into public.house_ineligibility_lists(id,organization_id,name) values(list,org,'Débutant');
 insert into public.house_ineligibility_editions(id,list_id,season_year) values(edition,list,2025);
 insert into public.house_class_rules(class_template_id,minimum_age,excluded_list_ids) values(ct,50,array[list]);
 perform set_config('request.jwt.claim.sub',staff::text,true);
 insert into public.platform_admins(user_id) values(profile);
 perform public.billing_set_capabilities(org,null,true,true,false);
 perform public.configure_reservation_billing(sh,'{"name_fr":"House TEST","name_en":"House TEST","account_prefix":"HT-A","receipt_prefix":"HT-R","invoice_prefix":"HT-I","closing_policy":"manual","payment_policy":"received_only","activation_policy":"allocated_received","categories":["manual"],"staff_roles":["admin","secretary"],"period":"2026","timezone":"America/Toronto"}','[]');
 delete from public.platform_admins where user_id=profile;
 set local role authenticated;
 a:=public.assess_house_classes(org,sh,horse,rider)->0;
 if (a->>'can_proceed')::boolean or a->'reasons'::text is null then raise exception 'Missing year or January age did not block';end if;
 update public.house_class_rules set age_basis='show_date',excluded_list_ids='{}' where class_template_id=ct;
 a:=public.assess_house_classes(org,sh,horse,rider)->0;
 if not(a->>'can_proceed')::boolean then raise exception 'Show-date age did not pass: %',a;end if;
 -- Membership exclusion follows its stable code across annual card editions.
 insert into public.organization_membership_types(id,organization_id,name,code,season_year,price,tax_applicable,valid_from,valid_until,is_public) values
 (pro,org,'Carte pro 2025','PRO',2025,0,false,'2025-01-01','2025-12-31',false),
 (pro_current,org,'Carte pro 2026','PRO',2026,0,false,'2026-01-01','2026-12-31',false);
 rows:=jsonb_build_array(jsonb_build_object('contact_id',rider,'valid_from','2026-01-01','valid_until','2026-12-31'));
 plan:=public.preview_membership_import(org,pro_current,rows,'complimentary');
 perform public.apply_membership_import(gen_random_uuid(),org,pro_current,rows,'complimentary',plan->>'token');
 update public.house_class_rules set excluded_membership_type_ids=array[pro] where class_template_id=ct;
 a:=public.assess_house_classes(org,sh,horse,rider)->0;
 if (a->>'can_proceed')::boolean then raise exception 'Current pro card bypassed stable membership code exclusion';end if;
 reset role;
 update public.contact_organization_memberships set status='cancelled' where contact_id=rider and membership_type_id=pro_current;
 a:=public.assess_house_classes(org,sh,horse,rider)->0;
 if not(a->>'can_proceed')::boolean then raise exception 'Cancelled pro card should not block';end if;
 update public.contact_organization_memberships set status='active',valid_until='2026-09-30' where contact_id=rider and membership_type_id=pro_current;
 a:=public.assess_house_classes(org,sh,horse,rider)->0;
 if not(a->>'can_proceed')::boolean then raise exception 'Card expired before show should not block';end if;
 delete from public.contact_organization_memberships where contact_id=rider and membership_type_id=pro_current;
 set local role authenticated;
 update public.house_class_rules set excluded_membership_type_ids='{}' where class_template_id=ct;
 update public.house_class_rules set require_membership=true where class_template_id=ct;
 a:=public.assess_house_classes(org,sh,horse,rider)->0;
 if (a->>'can_proceed')::boolean then raise exception 'Missing membership accepted';end if;
 update public.house_class_rules set require_membership=false,excluded_list_ids=array[list] where class_template_id=ct;
 insert into public.house_ineligibility_editions(list_id,season_year) values(list,2026) returning id into edition;
 perform public.import_house_ineligibility(edition,jsonb_build_array(jsonb_build_object('rider_name','Emilie Test')));
 a:=public.assess_house_classes(org,sh,horse,rider)->0;
 if (a->>'can_proceed')::boolean then raise exception 'Unlinked normalized name was not blocked';end if;
 blocked:=false;
 begin insert into public.entries(organization_id,show_id,horse_id,class_id,owner_contact_id,payer_contact_id,rider_contact_id,created_by_user_id,status) values(org,sh,horse,cl,rider,rider,rider,profile,'draft');exception when check_violation then blocked:=sqlerrm like '%HOUSE_ELIGIBILITY_BLOCKED%';end;
 if not blocked then raise exception 'Direct API insert bypassed house rules';end if;
 blocked:=false;
 begin insert into public.entries(organization_id,show_id,horse_id,class_id,owner_contact_id,payer_contact_id,rider_contact_id,created_by_user_id,status) values(org,sh,horse,cl,rider,rider,rider,profile,'completed');exception when check_violation then blocked:=sqlerrm like '%HOUSE_ELIGIBILITY_BLOCKED%';end;
 if not blocked then raise exception 'Final status bypassed house eligibility on creation';end if;
 blocked:=false;begin perform public.grant_house_eligibility_override(cl,horse,rider,'');exception when others then blocked:=true;end;
 if not blocked then raise exception 'Empty reason accepted';end if;
 override_id:=public.grant_house_eligibility_override(cl,horse,rider,'Exception documentée du secrétariat');
 a:=public.assess_house_classes(org,sh,horse,rider)->0;
 if not(a->>'can_proceed')::boolean or not(a->>'overridden')::boolean then raise exception 'Staff override failed';end if;
 if not exists(select 1 from public.house_eligibility_overrides where id=override_id and actor_id=profile and reason<>'') then raise exception 'Override audit missing';end if;
 perform public.import_house_ineligibility(edition,jsonb_build_array(jsonb_build_object('rider_name','Another Rider')));
 a:=public.assess_house_classes(org,sh,horse,rider)->0;
 if (a->>'can_proceed')::boolean then raise exception 'Changed list did not invalidate old override';end if;
 update public.house_class_rules set excluded_list_ids='{}' where class_template_id=ct;
 reset role;
 -- Only the horse's actual non-cancelled stall reservation for this show counts.
 update public.organization_health_policies set coggins_required=false,influenza_required=false,rhino_required=false,association_review_required=false,identity_validation_requirement='none' where organization_id=org;
 select id into day from public.show_days where show_id=sh order by day_date limit 1;
 insert into public.stall_options(id,organization_id,show_id,name,price,total_quantity,available_quantity,category,requires_horse_assignment) values(stall,org,sh,'Horse stall',0,100,100,'stall',true);
 insert into public.stall_bookings(id,organization_id,show_id,stall_option_id,horse_id,created_by_user_id,booker_contact_id,payer_contact_id,status,show_day_start_id,show_day_end_id,quantity,unit_price,total_price) values(booking,org,sh,stall,horse,profile,rider,rider,'reserved',day,day,1,0,0);
 if not exists(select 1 from public.entry_stabled_horses(sh) h where h.horse_id=horse) then raise exception 'Reserved horse missing from selector source';end if;
 update public.stall_bookings set status='cancelled' where id=booking;
 if exists(select 1 from public.entry_stabled_horses(sh) h where h.horse_id=horse) then raise exception 'Cancelled stall included in selector';end if;
 update public.stall_bookings set status='reserved' where id=booking;
 update public.stall_options set category='camping' where id=stall;
 if exists(select 1 from public.entry_stabled_horses(sh) h where h.horse_id=horse) then raise exception 'Camping included as horse stall';end if;
 update public.stall_options set category='stall',requires_horse_assignment=false where id=stall;
 if exists(select 1 from public.entry_stabled_horses(sh) h where h.horse_id=horse) then raise exception 'Tack stall included as horse stall';end if;
 update public.stall_options set requires_horse_assignment=true where id=stall;
 select id into nrha from public.governing_bodies where code='NRHA';
 insert into public.class_template_governing_bodies(class_template_id,governing_body_id,reporting_class_code,eligibility_profile_code) values(nrha_ct,nrha,'1000','non_pro');
 update public.house_class_rules set nrha_reference_template_id=nrha_ct where class_template_id=ct;
 a:=public.house_class_assessment(cl,horse,rider);
 if (a->>'can_proceed')::boolean then raise exception 'Missing NRHA number accepted';end if;
 select id into issuer from public.external_credential_issuers where upper(code)='NRHA';
 insert into public.contact_external_identifiers(contact_id,external_credential_issuer_id,identifier_type,identifier_value) values(rider,issuer,'membership','123456');
 insert into public.horse_external_identifiers(horse_id,external_credential_issuer_id,identifier_type,identifier_value) values(horse,issuer,'competition_license','654321');
 params:=public.house_nrha_parameters(cl,horse,rider);
 insert into public.house_nrha_checks(class_id,horse_id,rider_contact_id,fingerprint,eligible) values(cl,horse,rider,params->>'fingerprint',true);
 a:=public.house_class_assessment(cl,horse,rider);
 if not(a->>'can_proceed')::boolean then raise exception 'Verified NRHA reference did not pass: %',a;end if;
 update public.house_nrha_checks set expires_at=now()-interval '1 minute' where class_id=cl;
 a:=public.house_class_assessment(cl,horse,rider);
 if (a->>'can_proceed')::boolean or not(a->>'nrha_pending')::boolean then raise exception 'Expired check accepted';end if;
 perform set_config('request.jwt.claim.sub',outside_user::text,true);
 set local role authenticated;
 if exists(select 1 from public.entry_stabled_horses(sh)) then raise exception 'Another user can see private stabled horse ids';end if;
 if exists(select 1 from public.house_ineligibility_people) then raise exception 'Private lists leaked';end if;
 blocked:=false;begin perform public.assess_house_classes(org,sh,horse,rider);exception when insufficient_privilege then blocked:=true;end;
 if not blocked then raise exception 'Outsider assessed another team';end if;
 blocked:=false;begin perform public.grant_house_eligibility_override(cl,horse,rider,'Unauthorized override');exception when insufficient_privilege then blocked:=true;end;
 if not blocked then raise exception 'Outsider granted override';end if;
 reset role;
 if has_table_privilege('authenticated','public.house_nrha_checks','INSERT') or has_table_privilege('authenticated','public.house_eligibility_overrides','INSERT') or has_function_privilege('anon','public.assess_house_classes(uuid,uuid,uuid,uuid)','EXECUTE') then raise exception 'Privileged evidence exposed';end if;
end $$;
rollback;
